input.query:
PREFIX schema: <https://schema.org/> PREFIX aw: <https://w3id.org/agentweb-testbed#>
SELECT ?pname ?id ?lname ?rate ?apr ?rt ?term ?pay ?close ?amt ?pts WHERE {
?p a schema:MortgageLoan ; schema:name ?pname ; schema:identifier ?id ; schema:provider ?l ; schema:interestRate ?rate ; schema:annualPercentageRate ?apr ; schema:loanTerm [schema:value ?term] ; aw:rateType ?rt ; aw:estimatedMonthlyPayment [schema:value ?pay] ; aw:estimatedClosingCosts [schema:value ?close] ; aw:exampleLoanAmount [schema:value ?amt] .
?l schema:name ?lname .
OPTIONAL {?p aw:discountPoints ?pts}
FILTER(?term=30 && ?rt="fixed" && ?rate<=7.5 && ?pay<=3600 && ?close<=14500)
} ORDER BY ?rate LIMIT 15

